llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Chloramphenicol palmitate, a nitroaromatic-containing oral prodrug, has an absolute bioavailability of 85 ± 15% in children, showing that a p-nitrophenyl group is compatible with high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Roquinimex, a 4-hydroxy-2-oxo heterocycle structurally related to the 4-hydroxycoumarin core, shows complete oral bioavailability in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A coumarin-containing compound (Z18483535) has human oral bioavailability of 55.7%, well above the 20% threshold, supporting high F for the coumarin-based query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Lercanidipine has low absolute bioavailability (~10%) in fed patients due to extensive first-pass metabolism, but its dihydropyridine/ester scaffold and metabolic liability are not shared by the stable 4-hydroxycoumarin query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Nimodipine has low oral bioavailability (~13%) attributed to poor solubility and first-pass metabolism, but this dihydropyridine evidence has limited transferability to the acidic coumarin query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Naproxcinod has very low oral bioavailability because it is a nitrate-ester prodrug undergoing presystemic hydrolysis, a mechanism not applicable to the non-prodrug 4-hydroxycoumarin query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: the query is a p-nitro warfarin analog with a 4-hydroxycoumarin scaffold, a class known to be well absorbed orally. The most transferable experimental evidence—roquinimex (complete F), a coumarin-containing compound (55.7%), and nitroaromatic chloramphenicol palmitate (85%)—supports F ≥ 20%. Low-F records arise from dihydropyridines, prodrug esters, or organophosphates with distinct first-pass, solubility, or hydrolysis liabilities and are not mechanistically transferable.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query or a close warfarin analog was retrieved.",
    "All retrieved analogues have low Morgan similarity (<0.31), limiting direct structural transfer.",
    "No data specific to the solubility, permeability, or first-pass metabolism of 4-nitro warfarin are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

